import {diffusionFrame,cubeMeasures,exchangeCases}from './diffusion-models.js?v=20261023-physicscomplete01';
const text=(x,y,s,size=14)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${size}">${s}</text>`;
const svg=(label,body)=>`<svg class="shell-diagram" viewBox="0 0 480 330" role="img" aria-label="${label}"><defs><radialGradient id="diffParticle"><stop offset="0" stop-color="#fff0e5"/><stop offset=".45" stop-color="#ed8b78"/><stop offset="1" stop-color="#a85a4d"/></radialGradient></defs>${body}</svg>`;
export function diffusionFigure(settings={}){const f=diffusionFrame(settings),particles=(n,right)=>Array.from({length:n},(_,i)=>{const col=i%5,row=Math.floor(i/5),jitter=(f.step%3-1)*(i%2?3:-3);return`<circle cx="${(right?279:50)+col*30+jitter}" cy="${70+row*26+(i%2)*6}" r="7" fill="url(#diffParticle)" stroke="#f8f6f2" stroke-width=".5"/>`;}).join('');return svg(`Equal-volume compartments: left ${f.left} particles, right ${f.right}; last step ${f.lr} left to right and ${f.rl} right to left.`, `<rect x="20" y="35" width="440" height="220" rx="22" fill="#b7c8d6" fill-opacity=".08" stroke="#b7c8d6"/><path d="M236 35V255M244 35V255" stroke="#d4dfe7" stroke-width="2" stroke-dasharray="13 8"/><rect x="232" y="${145-40*f.area}" width="16" height="${80*f.area}" rx="5" fill="#ed8b78" fill-opacity=".3"/>${particles(f.left,false)}${particles(f.right,true)}${text(120,24,'LEFT · '+f.left)}${text(355,24,'RIGHT · '+f.right)}<path d="M175 278H305M295 272L305 278L295 284M305 304H175M185 298L175 304L185 310" fill="none" stroke="#ed8b78" stroke-width="2"/>${text(240,270,f.step?'Left → right: '+f.lr:'Membrane permits this substance',12)}${text(240,326,f.step?'Right → left: '+f.rl:'Equal compartment volumes',12)}`);}
export function surfaceFigure(side=1,depth=0){const m=cubeMeasures(side),s=55+side*19,x=240-s/2,y=130-s/2;const inset=s*Math.min(m.side/2,Math.max(0,depth))/m.side;return svg('Cube with edge '+m.side+' units. Six square faces.',`<path d="M${x} ${y}l35-28h${s}v${s}l-35 28Z" fill="#b7c8d6" fill-opacity=".55" stroke="#f8f6f2"/><rect x="${x}" y="${y}" width="${s}" height="${s}" fill="#ed8b78" fill-opacity=".65" stroke="#f8f6f2"/><path d="M${x+s} ${y}l35-28M${x} ${y}l35-28M${x+s} ${y+s}l35-28" stroke="#f8f6f2"/><rect x="${x+inset}" y="${y+inset}" width="${Math.max(0,s-2*inset)}" height="${Math.max(0,s-2*inset)}" fill="#526f86" stroke="#f8f6f2" stroke-width="1"/>${text(240,260,'Edge: '+side+' units')}${text(240,293,'Surface = 6 × edge² · volume = edge³',13)}`);}
export function exchangeFigure(id='lungs',adapted=true){const c=exchangeCases.find(c=>c.id===id)||exchangeCases[0];let body='';if(id==='lungs'){body='<ellipse cx="240" cy="135" rx="85" ry="75" fill="#ed8b78" fill-opacity=".3" stroke="#ed8b78" stroke-width="4"/><path d="M210 60V20H270V60" fill="none" stroke="#d4dfe7" stroke-width="6"/><path d="M135 75Q85 230 230 235Q375 240 345 75" fill="none" stroke="#b7c8d6" stroke-width="12"/>'+text(240,140,adapted?'Fresh air ↕':'No fresh air',17);}
else if(id==='intestine'){body=`<path d="M40 235${adapted?'Q55 235 65 150Q80 65 95 150Q105 235 120 235Q135 235 145 150Q160 65 175 150Q185 235 200 235Q215 235 225 150Q240 65 255 150Q265 235 280 235Q295 235 305 150Q320 65 335 150Q345 235 360 235Q375 235 385 150Q400 65 415 150Q425 235 440 235':'H440'}" fill="none" stroke="#ed8b78" stroke-width="7"/>`+text(240,35,'Gut contents')+text(240,285,adapted?'Folded surface':'Smooth counterfactual surface');}
else if(id==='gills'){body='<path d="M60 270L410 55" stroke="#d4dfe7" stroke-width="14"/>'+Array.from({length:7},(_,i)=>`<path d="M${100+i*43} ${245-i*26}l-35-75M${100+i*43} ${245-i*26}l50 45" stroke="#ed8b78" stroke-width="12"/>`).join('')+text(240,30,adapted?'Blood carries oxygen away':'Blood flow reduced');}
else if(id==='roots'){body=`<path d="M100 75H260V110${adapted?'H360Q410 130 360 150H260':'V150'}V225H100Z" stroke="#f8f6f2" fill="#ed8b78" fill-opacity=".35" stroke-width="3"/>`+Array.from({length:12},(_,i)=>`<circle cx="${65+(i%4)*100}" cy="${45+Math.floor(i/4)*100}" r="4" fill="#b7c8d6"/>`).join('')+text(240,285,adapted?'Projection contacts more soil':'Hair absent: less contact area');}
else{body=`<rect x="70" y="${adapted?100:60}" width="340" height="${adapted?95:190}" rx="25" fill="#b7c8d6" fill-opacity=".2" stroke="#d4dfe7" stroke-width="3"/>${adapted?'<ellipse cx="170" cy="145" rx="50" ry="24" fill="#182e44"/><ellipse cx="300" cy="145" rx="50" ry="24" fill="#182e44"/>':''}<path d="M240 290V${adapted?160:100}" stroke="#ed8b78" stroke-width="4" stroke-dasharray="7 4"/>`+text(240,30,adapted?'Thin leaf · internal air spaces':'Thick solid counterfactual');}if(id==='lungs'){body+=Array.from({length:adapted?12:4},(_,i)=>`<circle cx="${190+(i%4)*30}" cy="${100+Math.floor(i/4)*30}" r="5" fill="url(#diffParticle)"/>`).join('')+(adapted?'<path d="M225 25V65M220 58L225 65L230 58M255 65V25M250 32L255 25L260 32" fill="none" stroke="#ed8b78" stroke-width="3"/>':'<path d="M210 38H270" stroke="#ed8b78" stroke-width="5"/>');}if(id==='gills'){body+=`<path d="M85 265L415 65" stroke="${adapted?'#ed8b78':'#b7c8d6'}" stroke-width="4" stroke-dasharray="${adapted?'12 5':'2 6'}"/>`+Array.from({length:adapted?3:10},(_,i)=>`<circle cx="${140+(i%5)*40}" cy="${155+Math.floor(i/5)*24}" r="5" fill="url(#diffParticle)"/>`).join('');}return svg(c.name+', '+(adapted?c.on:c.off),body);}
